-- MyCurriculum — database tables (prefix mc_). Generated by tools/build-sql.php: edit lib/schema.php instead.
-- Import it in phpMyAdmin, then copy credentials-sample.php to credentials.php and fill it in.

CREATE TABLE IF NOT EXISTS `mc_meta` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_users` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(80) NOT NULL,
    `username` VARCHAR(30) NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `email_verified_at` DATETIME NULL,
    `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
    `google_sub` VARCHAR(64) NULL,
    `role` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
    `created_at` DATETIME NOT NULL,
    `last_login_at` DATETIME NULL,
    UNIQUE KEY `uq_email` (`email`),
    UNIQUE KEY `uq_username` (`username`),
    UNIQUE KEY `uq_google` (`google_sub`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_auth_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `csrf_token` CHAR(48) NOT NULL,
    `created_at` DATETIME NOT NULL,
    `last_seen_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_mc_tok_user` FOREIGN KEY (`user_id`) REFERENCES `mc_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_email_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `created_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_mc_etok_user` FOREIGN KEY (`user_id`) REFERENCES `mc_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_attempts` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `kind` VARCHAR(20) NOT NULL,
    `ip` VARCHAR(45) NOT NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_kind_ip` (`kind`, `ip`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_cvs` (
    `user_id` INT UNSIGNED NOT NULL PRIMARY KEY,
    `settings` TEXT NOT NULL,
    `profile` TEXT NOT NULL,
    `content` MEDIUMTEXT NOT NULL,
    `views` INT UNSIGNED NOT NULL DEFAULT 0,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NOT NULL,
    CONSTRAINT `fk_mc_cv_user` FOREIGN KEY (`user_id`) REFERENCES `mc_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mc_photos` (
    `user_id` INT UNSIGNED NOT NULL PRIMARY KEY,
    `mime` VARCHAR(20) NOT NULL,
    `data` MEDIUMBLOB NOT NULL,
    `hash` CHAR(16) NOT NULL,
    `updated_at` DATETIME NOT NULL,
    CONSTRAINT `fk_mc_photo_user` FOREIGN KEY (`user_id`) REFERENCES `mc_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `mc_meta` (k, v) VALUES ('schema_version', '1') ON DUPLICATE KEY UPDATE v = VALUES(v);
